package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 全局时钟配置：业务时间统一取 UTC，测试可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 生产默认使用 UTC 系统时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.portability;

/**
 * 携号转网流程状态。
 * AUTH_ISSUED：授权码已签发，待携出方确认；
 * CONFIRMED：携出方已确认，待生效窗口广播；
 * EFFECTIVE：已生效（终态）；
 * CANCELLED：已撤销（终态）。
 */
public enum FlowState {
    AUTH_ISSUED,
    CONFIRMED,
    EFFECTIVE,
    CANCELLED;

    /**
     * 是否为终态（已生效或已撤销）。
     */
    public boolean isTerminal() {
        return this == EFFECTIVE || this == CANCELLED;
    }
}

package com.example.starter.portability;

import java.time.Instant;

/**
 * 携号转网流程实体，对应 portability_flow 表。
 * authCode/authIssuedAt/authExpiresAt 为空表示尚未签发授权码；
 * 时间字段均为 UTC 口径。
 */
public record PortabilityFlow(
        Long id,
        String requestId,
        String msisdn,
        String donorOperator,
        String recipientOperator,
        FlowState state,
        String authCode,
        Instant authIssuedAt,
        Instant authExpiresAt,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.portability;

import java.time.Instant;

/**
 * 流程事件实体，对应 flow_event 表，按 id 升序即事件发生顺序。
 */
public record FlowEvent(
        Long id,
        Long flowId,
        String eventType,
        String detail,
        Instant createdAt) {
}

package com.example.starter.portability;

import java.time.Instant;

/**
 * 生效记录实体，对应 effective_record 表；同一流程至多一条（flow_id 唯一约束）。
 */
public record EffectiveRecord(
        Long id,
        Long flowId,
        String msisdn,
        String broadcastRequestId,
        Instant effectiveAt) {
}

package com.example.starter.portability;

import java.time.Instant;

/**
 * 幂等记录实体，对应 idempotency_record 表。
 * 指纹覆盖 requestId 与全部业务字段：同键同参重放首次结果，同键异参判 409。
 */
public record IdempotencyRecord(
        String endpoint,
        String requestId,
        String fingerprint,
        int responseStatus,
        String responseBody,
        Long flowId,
        Instant createdAt) {
}

package com.example.starter.portability;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码与稳定错误码，由全局异常处理器转换为统一错误报文。
 */
public class BusinessException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public BusinessException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }
}

