package com.example.starter.portability.web;

import java.time.Instant;
import java.time.LocalDate;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 携号转网申请请求。资格数据为合成数据，随申请一并提交：
 * hasUnpaidBill 是否存在欠费；contractEndDate 在网协议截止日（空表示无在网约定）；
 * lastPortedAt 上次携转完成时刻（UTC，空表示从未携转）。
 */
public record ApplyRequest(
        @NotBlank String requestId,
        @NotBlank String msisdn,
        @NotBlank String donorOperator,
        @NotBlank String recipientOperator,
        @NotNull Boolean hasUnpaidBill,
        LocalDate contractEndDate,
        Instant lastPortedAt) {
}

package com.example.starter.portability.web;

import jakarta.validation.constraints.NotBlank;

/**
 * 携出方确认请求，需携带申请时签发的授权码。
 */
public record ConfirmRequest(@NotBlank String authCode) {
}

package com.example.starter.portability.web;

import jakarta.validation.constraints.NotBlank;

/**
 * 生效广播请求，requestId 为幂等键：同键同参重放首次结果，同键异参返回 409。
 */
public record BroadcastRequest(@NotBlank String requestId) {
}

package com.example.starter.portability.web;

import java.time.Instant;

import com.example.starter.portability.FlowState;
import com.example.starter.portability.PortabilityFlow;

/**
 * 流程视图：申请、确认、撤销、查询的统一响应报文。
 */
public record FlowView(
        Long flowId,
        String requestId,
        String msisdn,
        String donorOperator,
        String recipientOperator,
        FlowState state,
        String authCode,
        Instant authIssuedAt,
        Instant authExpiresAt,
        Instant createdAt,
        Instant updatedAt) {

    public static FlowView from(PortabilityFlow flow) {
        return new FlowView(flow.id(), flow.requestId(), flow.msisdn(), flow.donorOperator(),
                flow.recipientOperator(), flow.state(), flow.authCode(), flow.authIssuedAt(),
                flow.authExpiresAt(), flow.createdAt(), flow.updatedAt());
    }
}

package com.example.starter.portability.web;

import java.time.Instant;

import com.example.starter.portability.FlowState;

/**
 * 生效广播响应：包含生效时刻与触发本次生效的幂等请求号。
 */
public record BroadcastView(
        Long flowId,
        String msisdn,
        FlowState state,
        String broadcastRequestId,
        Instant effectiveAt) {
}

package com.example.starter.portability.web;

import java.time.Instant;

import com.example.starter.portability.FlowEvent;

/**
 * 流程事件视图，按 id 升序返回。
 */
public record EventView(
        Long id,
        String eventType,
        String detail,
        Instant createdAt) {

    public static EventView from(FlowEvent event) {
        return new EventView(event.id(), event.eventType(), event.detail(), event.createdAt());
    }
}

package com.example.starter.portability.web;

/**
 * 统一错误报文：code 为稳定错误码，message 为人读说明。
 */
public record ErrorResponse(String code, String message) {
}

